public void linkActive()
{
    NDXMEDataFromExcelTable  lNDX_ME_DataFromExcelTable;

    if (element.args() && element.args().dataset() == tablenum(NDXMEDataFromExcelTable))
    {
        lNDX_ME_DataFromExcelTable = element.args().record();
        SysQuery::findOrCreateRange(NDXMEDataFromExcelTable_DS.query().dataSourceTable(tablenum(NDXMEDataFromExcelTable)), fieldnum(NDXMEDataFromExcelTable, RecId)).value(QueryValue(lNDX_ME_DataFromExcelTable.RecId));
        NDXMEDataFromExcelTable_DS.executeQuery();

        NDXMESumPerQuotation::refreshFromExcelTable(lNDX_ME_DataFromExcelTable.RecId);
        NDXMESumPerQuotation_DS.executeQuery();
    }

    super();
}

public void init()
{
    QueryBuildDataSource    qbds;
    super();

    qbds = this.query().dataSourceName(this.name());
    qbds.addSortField(fieldnum(NDXMEDataFromExcelTable, Grosshaendler));
    qbds.addSortField(fieldnum(NDXMEDataFromExcelTable, XLSFileNotice), SortOrder::Descending);
}

public int active()
{
    int ret;

    ret = super();
    NDXMESumPerQuotation::refreshFromExcelTable(NDXMEDataFromExcelTable.RecId);
    NDXMESumPerQuotation_DS.executeQuery();

    if(!NDXMESumPerQuotation)
    {
        NDXMESumPerQuotation_DS.active();
    }

    return ret;
}

public int active()
{
    int ret;

    ret = super();

    //Display SaleQuotation record for BV in SalesQuotationTable data source
    if (SalesQuotationTable.KCS_KBVBuildingProjectID)
    {
        qbrSalesQuotationTable_KCS_KBVBuildingProjectID.value(QueryValue(SalesQuotationTable.KCS_KBVBuildingProjectID));
        qbrSalesQuotationTable_QuotationId.value(SysQuery::valueNot(SalesQuotationTable.QuotationId));
    }
    else
    {
        qbrSalesQuotationTable_KCS_KBVBuildingProjectID.value('---');
    }

    SalesQuotationTableForBV_DS.executeQuery();

    return ret;
}

public void init()
{
    QueryBuildDataSource    qbds;
    ;
    super();
    qbds = this.query().dataSourceName(this.name());

    qbrSalesQuotationTable_KCS_KBVBuildingProjectID = qbds.addRange(fieldnum(SalesQuotationTable, KCS_KBVBuildingProjectID));
    qbrSalesQuotationTable_QuotationId              = qbds.addRange(fieldnum(SalesQuotationTable, QuotationId));

    qbrSalesQuotationTable_KCS_KBVBuildingProjectID.status(RangeStatus::Hidden);
    qbrSalesQuotationTable_QuotationId.status(RangeStatus::Hidden);
}
